def knapsack_01(weights, values, W):
    dp = [0] * (W + 1)  # dp[w]: 용량 w의 최대 가치
    for wi, vi in zip(weights, values):
        # 역순 순회: 물건을 한 번만 사용(0/1)
        for w in range(W, wi - 1, -1):
            dp[w] = max(dp[w], dp[w - wi] + vi)
    return dp[W]

def knapsack_fractional(items, W):  # items: (무게, 가치)
    items.sort(key=lambda x: x[1] / x[0], reverse=True)
    total = 0
    for wi, vi in items:
        if W <= 0:
            break
        take = min(wi, W)  # 남은 용량만큼 쪼개서 담음
        total += vi * take / wi
        W -= take
    return total
